package depchain;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import depchain.config.DepChainConfig;
import org.apache.tuweni.bytes.Bytes;
import org.hyperledger.besu.datatypes.Address;
import org.hyperledger.besu.datatypes.Wei;
import org.hyperledger.besu.evm.EvmSpecVersion;
import org.hyperledger.besu.evm.account.MutableAccount;
import org.hyperledger.besu.evm.fluent.EVMExecutor;
import org.hyperledger.besu.evm.fluent.SimpleWorld;
import org.hyperledger.besu.evm.frame.MessageFrame;
import org.hyperledger.besu.evm.tracing.StandardJsonTracer;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ContractExecutor {
    private static final String DEPLOYMENT_BYTECODE =
            "";
    private static final String RUNTIME_BYTECODE =
            "";
    private static final Map<String, String> scErrors = new HashMap();
    private final EVMExecutor executor;
    private final ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    private final PrintStream printStream = new PrintStream(byteArrayOutputStream);
    private final StandardJsonTracer tracer = new StandardJsonTracer(printStream, true, true, true, true);
    private final Map<String, MutableAccount> accounts = new HashMap<>();
    private final Lock lock = new ReentrantLock();

    public ContractExecutor(DepChainConfig config) {
        scErrors.put("118cdaa7", "OwnableUnauthorizedAccount");
        scErrors.put("e450d38c", "ERC20InsufficientBalance");
        scErrors.put("fb8f41b2", "ERC20InsufficientAllowance");
        SimpleWorld simpleWorld = new SimpleWorld();

        // Create owner account
        Address ownerAddress = Address.fromHexString(config.accountAddresses.get("10"));
        simpleWorld.createAccount(ownerAddress, 0, Wei.of(1000000));
        MutableAccount ownerAccount = (MutableAccount) simpleWorld.get(ownerAddress);
        accounts.put(ownerAddress.toUnprefixedHexString(), ownerAccount);

        // Create non-owner account
        Address aliceAddress = Address.fromHexString(config.accountAddresses.get("11"));
        simpleWorld.createAccount(aliceAddress, 0, Wei.of(1000));
        MutableAccount aliceAccount = (MutableAccount) simpleWorld.get(aliceAddress);
        accounts.put(aliceAddress.toUnprefixedHexString(), aliceAccount);

        // Create contract account
        Address contractAddress = Address.fromHexString("1234567891234567891234567891234567891234");
        simpleWorld.createAccount(contractAddress, 0, Wei.fromEth(0));
        MutableAccount contractAccount = (MutableAccount) simpleWorld.get(contractAddress);
        accounts.put(contractAddress.toUnprefixedHexString(), contractAccount);

        this.executor = EVMExecutor.evm(EvmSpecVersion.CANCUN);
        executor.tracer(tracer);
        executor.messageFrameType(MessageFrame.Type.CONTRACT_CREATION);
        executor.code(Bytes.fromHexString(DEPLOYMENT_BYTECODE));
        executor.sender(ownerAccount.getAddress());
        executor.receiver(contractAddress);
        executor.contract(contractAddress);
        executor.worldUpdater(simpleWorld.updater());
        // ?????? dont remove
        executor.gas(10_000_000L);
        executor.callData(Bytes.EMPTY);

        // Execute first contract creation
        executor.commitWorldState();
        executor.execute();

        executor.code(Bytes.fromHexString(RUNTIME_BYTECODE));
        executor.worldUpdater(simpleWorld.updater());
        executor.tracer(tracer);
        executor.receiver(contractAddress);
        executor.contract(contractAddress);
        executor.messageFrameType(MessageFrame.Type.MESSAGE_CALL);
    }

    public static String convertIntegerToHex256Bit(int number) {
        return convertLongToHex256Bit(number);
    }

    public static String convertLongToHex256Bit(long number) {
        BigInteger bigInt = BigInteger.valueOf(number);

        return String.format("%064x", bigInt);
    }

    public static String padHexStringTo256Bit(String hexString) {
        if (hexString.startsWith("0x")) {
            hexString = hexString.substring(2);
        }

        int length = hexString.length();
        int targetLength = 64;

        if (length >= targetLength) {
            return hexString.substring(0, targetLength);
        }

        return "0".repeat(targetLength - length) +
                hexString;
    }

    private static String extractReturnData(ByteArrayOutputStream byteArrayOutputStream) {
        String[] lines = byteArrayOutputStream.toString().split("\\r?\\n");
        JsonObject jsonObject = JsonParser.parseString(lines[lines.length - 1]).getAsJsonObject();

        String memory = jsonObject.get("memory").getAsString();

        JsonArray stack = jsonObject.get("stack").getAsJsonArray();
        int offset = Integer.decode(stack.get(stack.size() - 1).getAsString());
        int size = Integer.decode(stack.get(stack.size() - 2).getAsString());

        return memory.substring(2 + offset * 2, 2 + offset * 2 + size * 2);
    }

    private static String extractErrorFromReturnData(ByteArrayOutputStream byteArrayOutputStream) {
        String[] lines = byteArrayOutputStream.toString().split("\\r?\\n");
        JsonObject jsonObject = JsonParser.parseString(lines[lines.length - 1]).getAsJsonObject();
        JsonElement error = jsonObject.get("error");
        if (error != null) {
            String errorStr = scErrors.getOrDefault(error.getAsString().substring(2, 10), "");
            if (!errorStr.isEmpty()) {
                return errorStr;
            }
            return error.getAsString();
        } else {
            return "";
        }
    }

    private static int extractIntegerFromReturnData(ByteArrayOutputStream byteArrayOutputStream) {
        String returnData = extractReturnData(byteArrayOutputStream);
        return Integer.parseInt(returnData, 16);
    }

    private static long extractLongFromReturnData(ByteArrayOutputStream byteArrayOutputStream) {
        String returnData = extractReturnData(byteArrayOutputStream);
        return Long.parseLong(returnData, 16);
    }

    private static boolean extractBooleanFromReturnData(ByteArrayOutputStream byteArrayOutputStream) {
        // Parse the last byte (in Solidity, booleans are typically the last byte)
        // We'll check if the last byte is non-zero (true) or zero (false)
        String returnData = extractReturnData(byteArrayOutputStream);
        return !returnData.endsWith("00");
    }

    public boolean addToBlackList(String senderAddress, String targetAddress) throws InvalidOperationError {
        String paddedAddress = padHexStringTo256Bit(targetAddress);
        this.executor.sender(Address.fromHexString(senderAddress));
        this.executor.callData(Bytes.fromHexString("44337ea1" + paddedAddress));
        this.executor.commitWorldState();
        this.executor.execute();
        String error = extractErrorFromReturnData(byteArrayOutputStream);
        if (!error.isEmpty()) {
            throw new InvalidOperationError(error);
        }
        return extractBooleanFromReturnData(byteArrayOutputStream);
    }

    public boolean removeFromBlackList(String senderAddress, String targetAddress)
            throws InvalidOperationError {
        String paddedAddress = padHexStringTo256Bit(targetAddress);
        this.executor.sender(Address.fromHexString(senderAddress));
        this.executor.callData(Bytes.fromHexString("537df3b6" + paddedAddress));
        this.executor.commitWorldState();
        this.executor.execute();
        String error = extractErrorFromReturnData(byteArrayOutputStream);
        if (!error.isEmpty()) {
            throw new InvalidOperationError(error);
        }
        return extractBooleanFromReturnData(byteArrayOutputStream);
    }

    public boolean isBlackListed(String senderAddress, String targetAddress) throws InvalidOperationError {
        String paddedAddress = padHexStringTo256Bit(targetAddress);
        this.executor.sender(Address.fromHexString(senderAddress));
        this.executor.callData(Bytes.fromHexString("fe575a87" + paddedAddress));
        this.executor.commitWorldState();
        this.executor.execute();
        String error = extractErrorFromReturnData(byteArrayOutputStream);
        if (!error.isEmpty()) {
            throw new InvalidOperationError(error);
        }
        return extractBooleanFromReturnData(byteArrayOutputStream);
    }

    public Long getISTCoinBalance(String senderAddress) {
        String paddedAddress = padHexStringTo256Bit(senderAddress);
        this.executor.sender(Address.fromHexString(senderAddress));
        this.executor.callData(Bytes.fromHexString("70a08231" + paddedAddress));
        this.executor.commitWorldState();
        this.executor.execute();
        return extractLongFromReturnData(byteArrayOutputStream);
    }

    public void transferISTCoin(String senderAddress, String destAddress, Long amount)
            throws InvalidOperationError {
        String paddedDestAddress = padHexStringTo256Bit(destAddress);
        this.executor.sender(Address.fromHexString(senderAddress));
        this.executor.callData(
                Bytes.fromHexString("a9059cbb" + paddedDestAddress + convertLongToHex256Bit(amount)));
        this.executor.commitWorldState();
        this.executor.execute();
        String error = extractErrorFromReturnData(byteArrayOutputStream);
        if (!error.isEmpty()) {
            throw new InvalidOperationError(error);
        }
    }

    public void transferFromISTCoin(String senderAddress, String destAddress, Long amount)
            throws InvalidOperationError {
        String paddedSenderAddress = padHexStringTo256Bit(senderAddress);
        String paddedDestAddress = padHexStringTo256Bit(destAddress);
        this.executor.sender(Address.fromHexString(senderAddress));
        this.executor.callData(
                Bytes.fromHexString("23b872dd" + paddedSenderAddress + paddedDestAddress +
                        convertLongToHex256Bit(amount)));
        this.executor.commitWorldState();
        this.executor.execute();
        String error = extractErrorFromReturnData(byteArrayOutputStream);
        if (!error.isEmpty()) {
            throw new InvalidOperationError(error);
        }
    }

    public void transferDepCoin(String senderAddress, String destAddress, Long amount)
            throws InvalidOperationError {
        this.lock.lock();
        MutableAccount sender = this.accounts.get(senderAddress);
        MutableAccount receiver = this.accounts.get(destAddress);
        try {
            sender.decrementBalance(Wei.of(amount));
            receiver.incrementBalance(Wei.of(amount));
        } catch (IllegalStateException e) {
            throw new InvalidOperationError(e.getMessage());
        } finally {

            this.lock.unlock();
        }
    }

    public BigInteger getBalanceDepCoin(String senderAddress) {
        this.lock.lock();
        try {
            MutableAccount sender = this.accounts.get(senderAddress);
            System.out.println(sender);
            return sender.getBalance().toBigInteger();
        } finally {
            this.lock.unlock();
        }
    }
}
